import os, json, glob

# Look for likely data files in common locations
candidates = []
for root in [".", "/mnt/data", "/content", "data", "/home", "/tmp"]:
    if os.path.exists(root):
        for path in glob.glob(os.path.join(root, "**", "*"), recursive=True):
            if os.path.isfile(path):
                ext = os.path.splitext(path)[1].lower()
                if ext in {".csv", ".tsv", ".json", ".jsonl", ".parquet", ".xlsx", ".xls", ".feather", ".orc", ".txt", ".yaml", ".yml"}:
                    candidates.append(path)

for c in sorted(set(candidates)):
    try:
        print(f"{os.path.getsize(c):>12,} bytes  {c}")
    except OSError:
        pass

print("\nTotal candidate files:", len(set(candidates)))
